        $maintenance=['site_info','get_site_health','get_sitemap_status','list_plugins','list_plugin_updates','update_plugin_safely','list_plugin_checkpoints','restore_plugin_checkpoint','get_backup_schedule','update_backup_schedule','start_backup_job','get_job_status','list_jobs','cancel_job','create_backup','list_backups','get_backup_download_url','delete_backup','list_cron_events','flush_rewrite_rules','clear_cache','get_audit_log','export_audit_log','submit_approval_request','list_approval_requests','execute_approved_request'];
