            'content_manager'=>['label'=>'Content manager','short'=>'Pages and media','description'=>'Can manage pages, posts, menus, media and SEO content. Cannot manage plugins, themes or backups.','scopes'=>['site_read','content_read','content_write','media'],'tools'=>$content,'tone'=>'content'],
            'seo_marketing'=>['label'=>'SEO and marketing','short'=>'Visibility tools','description'=>'Can work on content, media, SEO fields, redirects and sitemap visibility without plugin or theme access.','scopes'=>['site_read','content_read','content_write','media','settings'],'tools'=>$seo,'tone'=>'seo'],
            'site_maintenance'=>['label'=>'Site maintenance','short'=>'Operations','description'=>'Can review health, manage private backups and perform controlled plugin and maintenance tasks.','scopes'=>['site_read','plugins','backups','maintenance','audit','settings'],'tools'=>$maintenance,'tone'=>'maintenance'],
            'administrator'=>['label'=>'Full site administrator','short'=>'All curated controls','description'=>'Can use every curated MCP capability. High-impact actions still require confirmation and WordPress permissions.','scopes'=>Xsofty_MCP_Auth::valid_scopes(),'tools'=>[],'tone'=>'danger'],
