    public static function scope_presets(): array {
        $definitions=self::preset_definitions();$presets=[];
        foreach($definitions as $key=>$definition)if($key!=='custom')$presets[$key]=$definition['scopes'];
        // Keep v0.3 form/API compatibility for previously selected preset keys.
        $presets['developer']=['site_read','content_read','content_write','media','plugins','theme_read','theme_write','settings','maintenance','audit'];
        $presets['backup_operator']=['site_read','backups','audit'];
        return $presets;
    }

    public static function normalize_token_input(array $input, ?int $now=null): array {
        $now=$now??time();$preset=sanitize_key((string)($input['preset']??'read_only'));$definitions=self::preset_definitions();$presets=self::scope_presets();
        $known=array_column(Xsofty_MCP_Tools::definitions(),'name');
        if($preset==='custom'){$scopes=(array)($input['scopes']??[]);$requested_tools=(array)($input['allowed_tools']??[]);}
        elseif(isset($definitions[$preset])){$scopes=$definitions[$preset]['scopes'];$requested_tools=$definitions[$preset]['tools'];}
        else{$scopes=$presets[$preset]??$presets['read_only'];$requested_tools=(array)($input['allowed_tools']??[]);}
        $scopes=array_values(array_unique(array_intersect(Xsofty_MCP_Auth::valid_scopes(),array_map('sanitize_key',$scopes))));$tools=[];
        foreach($requested_tools as $tool){$tool=sanitize_key((string)$tool);if(in_array($tool,$known,true)&&!in_array($tool,$tools,true))$tools[]=$tool;}
        if(array_key_exists('expires_at',$input)){$raw=trim((string)$input['expires_at']);$expires=$raw===''?0:strtotime($raw.' UTC');if($raw!==''&&$expires===false)throw new InvalidArgumentException('Invalid expiry date.');if($expires>$now+365*86400)throw new InvalidArgumentException('Expiry cannot exceed 365 days.');}
        else{$days=max(0,min(365,(int)($input['expiry_days']??0)));$expires=$days?$now+$days*86400:0;}
        return ['name'=>substr(sanitize_text_field((string)($input['name']??'')),0,80),'scopes'=>$scopes,'allowed_tools'=>$tools,'expires_at'=>(int)$expires,'rate_limit'=>max(10,min(600,(int)($input['rate_limit']??120))),'enabled'=>!array_key_exists('enabled',$input)||(bool)$input['enabled']];
    }

    public static function tool_groups(): array {
        $meta=[
            'site_read'=>['label'=>'Site overview','description'=>'General site, SEO and health information.','icon'=>'dashicons-chart-area'],
            'content_read'=>['label'=>'View content and SEO','description'=>'Read pages, posts, terms, menus and SEO information.','icon'=>'dashicons-visibility'],
            'content_write'=>['label'=>'Edit content and navigation','description'=>'Create, update, restore and remove editorial content.','icon'=>'dashicons-edit-page'],
            'media'=>['label'=>'Media library','description'=>'View and update images and attachment information.','icon'=>'dashicons-format-image'],
            'plugins'=>['label'=>'Plugins','description'=>'Controlled WordPress.org installs, updates and rollback checkpoints.','icon'=>'dashicons-admin-plugins'],
            'theme_read'=>['label'=>'View theme files','description'=>'Inspect files in the active theme without changing them.','icon'=>'dashicons-editor-code'],
            'theme_write'=>['label'=>'Edit safe theme assets','description'=>'Patch non-executable CSS, JSON, TXT and MD files only.','icon'=>'dashicons-art'],
            'settings'=>['label'=>'Settings, redirects and schedules','description'=>'Change approved settings, redirects and backup schedules.','icon'=>'dashicons-admin-settings'],
            'backups'=>['label'=>'Private backups','description'=>'Create, inspect, download and remove private site backups.','icon'=>'dashicons-database'],
            'maintenance'=>['label'=>'Maintenance','description'=>'Inspect scheduled tasks, clear caches and refresh rewrite rules.','icon'=>'dashicons-admin-tools'],
            'audit'=>['label'=>'Activity and approvals','description'=>'Review activity, request approval and execute approved work.','icon'=>'dashicons-yes-alt'],
        ];
        foreach($meta as &$group)$group['tools']=[];unset($group);
        foreach(Xsofty_MCP_Tools::definitions() as $tool)if(isset($meta[$tool['scope']]))$meta[$tool['scope']]['tools'][]=$tool;
        return $meta;
    }

    private static function friendly_tool_name(string $name):string {
        $manual=['site_info'=>'View site overview','get_site_health'=>'Review site health','get_seo_status'=>'Review SEO setup','get_sitemap_status'=>'Review sitemap status','list_cron_events'=>'View scheduled tasks','run_cron_event'=>'Run a scheduled task','flush_rewrite_rules'=>'Refresh website links','clear_cache'=>'Clear site cache','update_plugin_safely'=>'Update a plugin with rollback','get_backup_download_url'=>'Create a secure download link','submit_approval_request'=>'Request administrator approval','execute_approved_request'=>'Run approved work','get_audit_log'=>'View activity history','export_audit_log'=>'Export activity history'];
        if(isset($manual[$name]))return $manual[$name];
        $verbs=['get_'=>'View ','list_'=>'List ','create_'=>'Create ','update_'=>'Update ','delete_'=>'Delete ','restore_'=>'Restore ','set_'=>'Set ','upload_'=>'Upload ','install_'=>'Install ','activate_'=>'Activate ','deactivate_'=>'Deactivate ','start_'=>'Start ','cancel_'=>'Cancel ','upsert_'=>'Create or update ','read_'=>'Read ','patch_'=>'Edit ','export_'=>'Export '];
        foreach($verbs as $prefix=>$verb)if(str_starts_with($name,$prefix))return $verb.ucfirst(str_replace('_',' ',substr($name,strlen($prefix))));
        return ucfirst(str_replace('_',' ',$name));
    }

    public static function init(): void {
        add_action('admin_menu',[self::class,'menu']);add_action('admin_enqueue_scripts',[self::class,'assets']);
        add_action('admin_post_xsofty_mcp_save',[self::class,'save']);add_action('admin_post_xsofty_mcp_generate',[self::class,'generate']);add_action('admin_post_xsofty_mcp_token_create',[self::class,'create_token']);add_action('admin_post_xsofty_mcp_token_update',[self::class,'update_token']);add_action('admin_post_xsofty_mcp_token_revoke',[self::class,'revoke_token']);add_action('admin_post_xsofty_mcp_revoke',[self::class,'revoke']);
        if(defined('WP_CLI')&&WP_CLI)Xsofty_MCP_CLI::register();
    }

    public static function menu(): void {add_options_page('Xsofty WordPress MCP','Xsofty MCP','manage_options','xsofty-wordpress-mcp',[self::class,'page']);}
    public static function assets(string $hook):void {if($hook!=='settings_page_xsofty-wordpress-mcp')return;$base=plugin_dir_url(XSOFTY_WP_MCP_FILE);wp_enqueue_style('dashicons');wp_enqueue_style('xsofty-mcp-admin',$base.'assets/admin.css',[],XSOFTY_WP_MCP_VERSION);wp_enqueue_script('xsofty-mcp-admin',$base.'assets/admin.js',[],XSOFTY_WP_MCP_VERSION,true);}
    private static function require_admin():void {if(!current_user_can('manage_options'))wp_die('You do not have permission to manage MCP access.');}
    private static function redirect(array $args=[]):void {wp_safe_redirect(add_query_arg(array_merge(['page'=>'xsofty-wordpress-mcp'],$args),admin_url('options-general.php')));exit;}
    private static function render_token_once(array $created):void {nocache_headers();header('X-Frame-Options: DENY');$back=admin_url('options-general.php?page=xsofty-wordpress-mcp');$message='<div style="max-width:720px;margin:32px auto;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif"><h1>Connection created</h1><p><strong>Copy this access token now. It will not be shown again.</strong></p><p><code style="display:block;padding:16px;border:1px solid #c3c4c7;background:#fff;word-break:break-all">'.esc_html((string)$created['token']).'</code></p><p>Store it in a password manager or protected environment file. Never paste it into a public document.</p><p><a class="button button-primary" href="'.esc_url($back).'">Return to MCP control center</a></p></div>';wp_die($message,'MCP connection created',['response'=>200,'back_link'=>false]);}
    private static function nonce_field(string $action):void {echo '<input type="hidden" name="_wpnonce" value="'.esc_attr(wp_create_nonce($action)).'">';}

    public static function save():void {
        self::require_admin();check_admin_referer('xsofty_mcp_save');$backup=Xsofty_MCP_Jobs::normalize_schedule((string)($_POST['backup_schedule']??'disabled'),(int)($_POST['backup_retention']??5));
        $origins=preg_split('/\r\n|\r|\n/',(string)($_POST['allowed_origins']??''));$origins=array_values(array_filter(array_map(static function($origin){$origin=untrailingslashit(esc_url_raw(trim($origin)));return str_starts_with($origin,'https://')?$origin:'';},$origins)));
        $known=array_column(Xsofty_MCP_Tools::definitions(),'name');$enabled=array_values(array_intersect($known,array_map('sanitize_key',(array)($_POST['enabled_tools']??[]))));$disabled=array_values(array_diff($known,$enabled));
        try{Xsofty_MCP_Auth::update_settings(function(array $settings)use($origins,$disabled):array {$settings['enabled']=isset($_POST['enabled']);$settings['allow_http']=isset($_POST['allow_http']);$settings['allow_cron_run']=isset($_POST['allow_cron_run']);$settings['rate_limit']=max(10,min(600,(int)($_POST['rate_limit']??120)));$settings['allowed_origins']=$origins;$settings['disabled_tools']=$disabled;return $settings;});Xsofty_MCP_Jobs::update_schedule($backup['schedule'],$backup['retention']);Xsofty_MCP_Auth::audit('settings_updated',true);self::redirect(['updated'=>'1']);}
        catch(Throwable $error){Xsofty_MCP_Auth::audit('settings_updated',false,['error'=>substr($error->getMessage(),0,160)]);self::redirect(['error'=>rawurlencode(substr($error->getMessage(),0,160))]);}
    }

    public static function create_token():void {self::require_admin();check_admin_referer('xsofty_mcp_token_create');$input=self::normalize_token_input(wp_unslash($_POST));try{$created=Xsofty_MCP_Auth::create_token($input['name'],get_current_user_id(),$input['scopes'],$input['expires_at'],$input['allowed_tools']);Xsofty_MCP_Auth::update_token($created['id'],['rate_limit'=>$input['rate_limit'],'enabled'=>true]);self::render_token_once($created);}catch(Throwable $error){self::redirect(['error'=>rawurlencode(substr($error->getMessage(),0,160))]);}}
    public static function generate():void {self::create_token();}
    public static function update_token():void {self::require_admin();check_admin_referer('xsofty_mcp_token_update');$id=sanitize_key((string)($_POST['token_id']??''));$input=self::normalize_token_input(wp_unslash($_POST));try{if(!Xsofty_MCP_Auth::update_token($id,$input))throw new RuntimeException('Connection not found.');self::redirect(['updated'=>'1']);}catch(Throwable $error){self::redirect(['error'=>rawurlencode(substr($error->getMessage(),0,160))]);}}
    public static function revoke_token():void {self::require_admin();check_admin_referer('xsofty_mcp_token_revoke');$id=sanitize_key((string)($_POST['token_id']??''));if($id!=='')Xsofty_MCP_Auth::revoke_token($id);self::redirect(['revoked'=>'1']);}
    public static function revoke():void {self::require_admin();check_admin_referer('xsofty_mcp_revoke');Xsofty_MCP_Auth::revoke();self::redirect(['revoked'=>'1']);}

    private static function scope_labels():array {return ['site_read'=>'Site overview','content_read'=>'View content and SEO','content_write'=>'Edit content and navigation','media'=>'Media library','plugins'=>'Plugin operations','theme_read'=>'View active-theme files','theme_write'=>'Edit safe theme assets','settings'=>'Settings, redirects and schedules','backups'=>'Private backups','maintenance'=>'Maintenance actions','audit'=>'Activity and approvals'];}
    private static function scope_summary(array $scopes):string {$labels=self::scope_labels();$names=[];foreach($scopes as $scope)if(isset($labels[$scope]))$names[]=$labels[$scope];return implode(', ',$names);}

