    private static function tool_picker(array $allowed,bool $global=false,array $disabled=[]):void {?>
        <div class="xwmcp-tools" data-tool-picker><div class="xwmcp-tools__bar"><label><span class="screen-reader-text">Search tools</span><input type="search" class="xwmcp-tool-search" placeholder="Search capabilities or technical names"></label><span class="xwmcp-tool-count" aria-live="polite"></span></div>
        <?php foreach(self::tool_groups() as $scope=>$group): ?><details class="xwmcp-tool-group" data-tool-group><summary><span class="dashicons <?php echo esc_attr($group['icon']); ?>" aria-hidden="true"></span><span><strong><?php echo esc_html($group['label']); ?></strong><small><?php echo esc_html($group['description']); ?></small></span><span class="xwmcp-count"><?php echo esc_html((string)count($group['tools'])); ?></span></summary><div class="xwmcp-tool-list">
        <?php foreach($group['tools'] as $tool): $checked=$global?!in_array($tool['name'],$disabled,true):in_array($tool['name'],$allowed,true); ?><label class="xwmcp-tool" data-tool-search-text="<?php echo esc_attr(strtolower(self::friendly_tool_name($tool['name']).' '.$tool['name'].' '.$tool['description'])); ?>"><input type="checkbox" name="<?php echo $global?'enabled_tools':'allowed_tools'; ?>[]" value="<?php echo esc_attr($tool['name']); ?>" <?php checked($checked); ?>><span><strong><?php echo esc_html(self::friendly_tool_name($tool['name'])); ?></strong><small><?php echo esc_html($tool['description']); ?></small><code><?php echo esc_html($tool['name']); ?></code></span></label><?php endforeach; ?>
        </div></details><?php endforeach; ?></div><?php
    }

    private static function token_form(array $record=[]):void {
        $editing=!empty($record);$id=(string)($record['id']??'');$scopes=(array)($record['scopes']??self::scope_presets()['read_only']);$allowed=(array)($record['allowed_tools']??self::preset_definitions()['read_only']['tools']);$expires=(int)($record['expires_at']??0);$expiry_value=$expires?gmdate('Y-m-d\TH:i',$expires):'';$selected=$editing?'custom':'read_only';
        ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="xwmcp-connection-form" data-connection-form>
        <input type="hidden" name="action" value="<?php echo esc_attr($editing?'xsofty_mcp_token_update':'xsofty_mcp_token_create'); ?>"><?php if($editing): ?><input type="hidden" name="token_id" value="<?php echo esc_attr($id); ?>"><?php endif; ?><?php self::nonce_field($editing?'xsofty_mcp_token_update':'xsofty_mcp_token_create'); ?>
        <div class="xwmcp-form-grid"><label class="xwmcp-field"><span>Connection name</span><input class="regular-text" required maxlength="80" name="name" placeholder="For example: Content team" value="<?php echo esc_attr($record['name']??''); ?>"><small>Use a name that identifies the person, team or assistant.</small></label><label class="xwmcp-field"><span>Expiry</span><input type="datetime-local" name="expires_at" value="<?php echo esc_attr($expiry_value); ?>"><small>UTC. Leave blank for no automatic expiry.</small></label><label class="xwmcp-field"><span>Request limit</span><span class="xwmcp-input-unit"><input type="number" min="10" max="600" name="rate_limit" value="<?php echo esc_attr($record['rate_limit']??120); ?>"><em>per minute</em></span><small>Protects the site from excessive requests.</small></label><?php if($editing): ?><label class="xwmcp-field"><span>Connection status</span><span class="xwmcp-switch-row"><input type="checkbox" name="enabled" value="1" <?php checked(!empty($record['enabled'])); ?>><strong>Enabled</strong></span><small>Disable temporarily without revoking the token.</small></label><?php endif; ?></div>
        <?php self::preset_picker($selected);self::scope_picker($scopes); ?><details class="xwmcp-advanced" data-advanced-tools><summary>Customize individual tools <span>Advanced</span></summary><p class="xwmcp-help">With Custom access, leave every tool unchecked to allow every tool covered by the selected capability groups.</p><?php self::tool_picker($allowed); ?></details>
        <div class="xwmcp-form-actions"><?php submit_button($editing?'Save connection':'Create secure connection',$editing?'secondary':'primary','submit',false,['id'=>$editing?'xwmcp-save-connection-'.$id:'xwmcp-create-connection']); ?><span>Changes are validated against WordPress permissions when used.</span></div></form><?php
    }

    private static function connection_card(array $record):void {$expires=(int)($record['expires_at']??0);$expired=$expires&&$expires<time();$enabled=!empty($record['enabled'])&&!$expired;$last=(int)($record['last_used_at']??0);?>
        <article class="xwmcp-connection-card"><div class="xwmcp-connection-card__head"><div><span class="xwmcp-status xwmcp-status--<?php echo $enabled?'good':'muted'; ?>"><i aria-hidden="true"></i><?php echo $expired?'Expired':($enabled?'Active':'Disabled'); ?></span><h3><?php echo esc_html((string)$record['name']); ?></h3><p><?php echo esc_html(self::scope_summary((array)$record['scopes'])); ?></p></div><span class="dashicons dashicons-admin-network" aria-hidden="true"></span></div><dl><div><dt>Expires</dt><dd><?php echo $expires?esc_html(gmdate('M j, Y',$expires).' UTC'):'Never'; ?></dd></div><div><dt>Last used</dt><dd><?php echo $last?esc_html(human_time_diff($last,time()).' ago'):'Not yet'; ?></dd></div><div><dt>Tool access</dt><dd><?php $count=count((array)($record['allowed_tools']??[]));echo $count?esc_html($count.' selected'):'All within capabilities'; ?></dd></div></dl>
        <details class="xwmcp-manage"><summary>Manage connection</summary><?php self::token_form($record); ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="xwmcp-revoke" onsubmit="return confirm('Permanently revoke this connection? The existing token will stop working immediately.');"><input type="hidden" name="action" value="xsofty_mcp_token_revoke"><input type="hidden" name="token_id" value="<?php echo esc_attr($record['id']); ?>"><?php self::nonce_field('xsofty_mcp_token_revoke');submit_button('Revoke permanently','delete','submit',false,['id'=>'xwmcp-revoke-connection-'.$record['id']]);?></form></details></article><?php
    }

    public static function page():void {
        self::require_admin();$settings=Xsofty_MCP_Auth::settings();$records=Xsofty_MCP_Auth::token_records();$known=array_column(Xsofty_MCP_Tools::definitions(),'name');$disabled=(array)($settings['disabled_tools']??[]);$active=count(array_filter($records,static fn($r)=>!empty($r['enabled'])&&(!(int)($r['expires_at']??0)||(int)$r['expires_at']>=time())));$schedule=Xsofty_MCP_Jobs::schedule_settings();$enabled_count=count(array_diff($known,$disabled));$preset_data=[];foreach(self::preset_definitions() as $key=>$preset)$preset_data[$key]=['label'=>$preset['label'],'description'=>$preset['description'],'scopes'=>$preset['scopes'],'tools'=>$preset['tools']];
        ?><div class="wrap xwmcp-wrap"><script type="application/json" id="xwmcp-preset-data"><?php echo wp_json_encode($preset_data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE); ?></script>
        <header class="xwmcp-hero"><div><span class="xwmcp-eyebrow">Xsofty WordPress MCP</span><h1>AI access, under your control.</h1><p>Connect trusted assistants to WordPress without exposing passwords, server access or unrestricted code execution.</p></div><div class="xwmcp-hero__state"><span class="xwmcp-status xwmcp-status--<?php echo !empty($settings['enabled'])?'good':'muted'; ?>"><i aria-hidden="true"></i><?php echo !empty($settings['enabled'])?'Bridge enabled':'Bridge paused'; ?></span><small>Version <?php echo esc_html(XSOFTY_WP_MCP_VERSION); ?></small></div></header>
        <?php if(!empty($_GET['error'])): ?><div class="notice notice-error"><p><?php echo esc_html(sanitize_text_field(wp_unslash($_GET['error']))); ?></p></div><?php elseif(!empty($_GET['updated'])): ?><div class="notice notice-success is-dismissible"><p>Settings saved.</p></div><?php elseif(!empty($_GET['revoked'])): ?><div class="notice notice-success is-dismissible"><p>Connection revoked.</p></div><?php endif; ?>
        <nav class="xwmcp-nav" aria-label="MCP settings sections"><a href="#xwmcp-overview">Overview</a><a href="#xwmcp-connections">Connections</a><a href="#xwmcp-controls">Safety and tools</a><a href="#xwmcp-activity">Activity</a><a href="#xwmcp-connect">Setup</a></nav>

        <section id="xwmcp-overview" class="xwmcp-section"><div class="xwmcp-section__head"><div><span class="xwmcp-kicker">Overview</span><h2>Everything important at a glance</h2></div></div><div class="xwmcp-stat-grid"><article><span class="dashicons dashicons-admin-network" aria-hidden="true"></span><strong><?php echo esc_html((string)$active); ?></strong><small>Active connections</small></article><article><span class="dashicons dashicons-admin-tools" aria-hidden="true"></span><strong><?php echo esc_html($enabled_count.' / '.count($known)); ?></strong><small>Tools available globally</small></article><article><span class="dashicons dashicons-backup" aria-hidden="true"></span><strong><?php echo esc_html(ucfirst($schedule['schedule'])); ?></strong><small>Backup schedule</small></article><article><span class="dashicons dashicons-shield" aria-hidden="true"></span><strong><?php echo is_ssl()?'HTTPS':(!empty($settings['allow_http'])?'Local HTTP':'HTTP blocked'); ?></strong><small>Connection protection</small></article></div><div class="xwmcp-endpoint"><div><span>MCP endpoint</span><code id="xwmcp-endpoint-value"><?php echo esc_html(rest_url('xsofty-mcp/v1/mcp')); ?></code></div><button type="button" class="button" data-copy-target="xwmcp-endpoint-value"><span class="dashicons dashicons-admin-page" aria-hidden="true"></span> Copy endpoint</button></div></section>

        <section id="xwmcp-connections" class="xwmcp-section"><div class="xwmcp-section__head"><div><span class="xwmcp-kicker">Connections</span><h2>Who can access this site?</h2><p>Every person or assistant receives a separate, revocable connection with only the access it needs.</p></div><span class="xwmcp-section__metric"><?php echo esc_html((string)count($records)); ?> configured</span></div><?php if(!$records): ?><div class="xwmcp-empty"><span class="dashicons dashicons-lock" aria-hidden="true"></span><h3>No connections yet</h3><p>Create a read-only connection to start safely.</p></div><?php else: ?><div class="xwmcp-connection-grid"><?php foreach($records as $record)self::connection_card($record); ?></div><?php endif; ?><details class="xwmcp-create" <?php echo !$records?'open':''; ?>><summary><span class="dashicons dashicons-plus-alt2" aria-hidden="true"></span><span><strong>Create a new connection</strong><small>Choose a preset, name it, then copy the one-time token.</small></span></summary><?php self::token_form(); ?></details></section>

        <section id="xwmcp-controls" class="xwmcp-section"><div class="xwmcp-section__head"><div><span class="xwmcp-kicker">Safety and tools</span><h2>Site-wide guardrails</h2><p>These controls apply to every connection. Individual access can only become more restricted, never broader.</p></div></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="xwmcp-global-form"><input type="hidden" name="action" value="xsofty_mcp_save"><?php self::nonce_field('xsofty_mcp_save'); ?>
        <div class="xwmcp-settings-grid"><article class="xwmcp-settings-card"><div class="xwmcp-card-title"><span class="dashicons dashicons-controls-play" aria-hidden="true"></span><div><h3>Bridge availability</h3><p>Pause every MCP connection without deleting it.</p></div></div><label class="xwmcp-toggle"><input type="checkbox" name="enabled" value="1" <?php checked($settings['enabled']); ?>><span aria-hidden="true"></span><strong>Allow MCP connections</strong></label><label class="xwmcp-field"><span>Default request limit</span><span class="xwmcp-input-unit"><input type="number" min="10" max="600" name="rate_limit" value="<?php echo esc_attr($settings['rate_limit']); ?>"><em>per minute</em></span><small>Individual connections can use a lower or higher bounded limit.</small></label></article>
        <article class="xwmcp-settings-card"><div class="xwmcp-card-title"><span class="dashicons dashicons-backup" aria-hidden="true"></span><div><h3>Scheduled private backups</h3><p>Backups stay outside the public website directory.</p></div></div><div class="xwmcp-inline-fields"><label class="xwmcp-field"><span>Schedule</span><select name="backup_schedule"><option value="disabled" <?php selected($settings['backup_schedule']??'disabled','disabled'); ?>>Off</option><option value="daily" <?php selected($settings['backup_schedule']??'disabled','daily'); ?>>Every day</option><option value="weekly" <?php selected($settings['backup_schedule']??'disabled','weekly'); ?>>Every week</option></select></label><label class="xwmcp-field"><span>Keep</span><span class="xwmcp-input-unit"><input type="number" min="1" max="20" name="backup_retention" value="<?php echo esc_attr((int)($settings['backup_retention']??5)); ?>"><em>backups</em></span></label></div><p class="xwmcp-callout"><span class="dashicons dashicons-info-outline" aria-hidden="true"></span>Complete backups contain site files and database content. Give backup access only to trusted administrators.</p></article></div>
        <article class="xwmcp-settings-card xwmcp-settings-card--wide"><div class="xwmcp-card-title"><span class="dashicons dashicons-shield-alt" aria-hidden="true"></span><div><h3>High-impact actions</h3><p>Keep uncommon or sensitive operations off unless they are required.</p></div></div><div class="xwmcp-guardrails"><label class="xwmcp-toggle"><input type="checkbox" name="allow_cron_run" value="1" <?php checked(!empty($settings['allow_cron_run'])); ?>><span aria-hidden="true"></span><strong>Allow manual scheduled-task runs</strong><small>Only existing registered events can run; arguments are never exposed.</small></label><label class="xwmcp-toggle"><input type="checkbox" name="allow_http" value="1" <?php checked($settings['allow_http']); ?>><span aria-hidden="true"></span><strong>Allow unencrypted local connections</strong><small>Works only on loopback, private-network or <code>.local</code> hosts. Live sites require HTTPS.</small></label></div><details class="xwmcp-advanced"><summary>Browser origin allowlist <span>Advanced</span></summary><label class="xwmcp-field"><span>Approved browser applications</span><textarea name="allowed_origins" rows="4" class="large-text code" placeholder="https://control.example.com"><?php echo esc_textarea(implode("\n",(array)$settings['allowed_origins'])); ?></textarea><small>Optional HTTPS origins, one per line. Normal non-browser MCP clients do not send an Origin header.</small></label></details></article>
        <article class="xwmcp-settings-card xwmcp-settings-card--wide"><div class="xwmcp-card-title xwmcp-card-title--tools"><span class="dashicons dashicons-admin-generic" aria-hidden="true"></span><div><h3>Globally available tools</h3><p>Disable a tool here to remove it from every connection immediately.</p></div><span class="xwmcp-section__metric"><?php echo esc_html($enabled_count.' enabled'); ?></span></div><div class="xwmcp-quick-presets"><span>Quick setup</span><button type="button" class="button" data-global-preset="read_only">Viewing only</button><button type="button" class="button" data-global-preset="content_manager">Content work</button><button type="button" class="button" data-global-preset="site_maintenance">Maintenance</button><button type="button" class="button" data-global-preset="administrator">Enable all</button></div><?php self::tool_picker([],true,$disabled); ?></article>
        <div class="xwmcp-savebar"><div><strong>Review before saving</strong><span>Changes affect every connection on this site.</span></div><?php submit_button('Save site-wide settings','primary','submit',false,['id'=>'xwmcp-save-site-settings']); ?></div></form></section>

        <section id="xwmcp-activity" class="xwmcp-section"><div class="xwmcp-section__head"><div><span class="xwmcp-kicker">Activity</span><h2>Administrator approvals</h2><p>Review sensitive requests before an assistant can execute them.</p></div></div><div class="xwmcp-activity-card"><?php Xsofty_MCP_Control::render_admin(); ?></div></section>

        <section id="xwmcp-connect" class="xwmcp-section"><div class="xwmcp-section__head"><div><span class="xwmcp-kicker">Setup</span><h2>Connect Hermes securely</h2><p>Store the one-time token in an environment variable. Never paste a real token into configuration files or source control.</p></div></div><div class="xwmcp-code-card"><div><span>Hermes configuration</span><button type="button" class="button button-small" data-copy-target="xwmcp-hermes-code">Copy example</button></div><pre id="xwmcp-hermes-code">mcp_servers:
  wordpress-site:
    url: <?php echo esc_html(rest_url('xsofty-mcp/v1/mcp')); ?>
    headers:
      Authorization: "Bearer ${WORDPRESS_MCP_TOKEN}"
    enabled: true</pre></div><ol class="xwmcp-steps"><li><strong>Create a connection</strong><span>Choose the least powerful preset that can do the job.</span></li><li><strong>Copy the token once</strong><span>Store it in a protected environment variable or password manager.</span></li><li><strong>Add the endpoint</strong><span>Use the example above, then test connection and tool discovery.</span></li></ol></section>
        </div><?php
    }
}

if(defined('WP_CLI')&&WP_CLI){
    final class Xsofty_MCP_CLI {
        public static function register():void{WP_CLI::add_command('xsofty-mcp',self::class);}
        /** Create, list or revoke named MCP tokens. */
        public function token(array $args,array $assoc):void{$action=$args[0]??'create';if($action==='create'){$name=sanitize_text_field($assoc['name']??'CLI connection');$days=max(0,min(365,(int)($assoc['expires']??0)));$scopes=isset($assoc['scopes'])?explode(',',(string)$assoc['scopes']):null;$tools=isset($assoc['tools'])?explode(',',(string)$assoc['tools']):[];$created=Xsofty_MCP_Auth::create_token($name,0,$scopes,$days?time()+$days*86400:0,$tools);WP_CLI::line('TOKEN_ID='.$created['id']);WP_CLI::line('TOKEN='.$created['token']);return;}if($action==='list'){$items=[];foreach(Xsofty_MCP_Auth::token_records() as $r){unset($r['token_hash'],$r['download_key']);$items[]=$r;}WP_CLI::line(wp_json_encode($items,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));return;}if($action==='revoke'){$id=sanitize_key($args[1]??'');if($id===''||!Xsofty_MCP_Auth::revoke_token($id))WP_CLI::error('Token not found.');WP_CLI::success('MCP token revoked.');return;}WP_CLI::error('Use: wp xsofty-mcp token create|list|revoke <id>');}
        /** Show bridge status without revealing credentials. */
        public function status():void{$s=Xsofty_MCP_Auth::settings();WP_CLI::line(wp_json_encode(['enabled'=>(bool)$s['enabled'],'connections'=>count(Xsofty_MCP_Auth::token_records()),'endpoint'=>rest_url('xsofty-mcp/v1/mcp'),'globally_disabled_tools'=>(array)$s['disabled_tools']],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));}
        /** Create a complete local backup. */
        public function backup(array $args,array $assoc):void{$result=Xsofty_MCP_Backups::create(sanitize_text_field($assoc['label']??'cli'));WP_CLI::line(wp_json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));}
    }
}
